 function download(name,content,type){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function scheduleFood(item){const keys=[item?.key,item?.foodKey,item?.food_key,item?.id].filter(Boolean).map(String),catalog={...(typeof FOOD_DB!=="undefined"?FOOD_DB:{}),...(state.customFoods||{})};let found=null;for(const key of keys){if(catalog[key]){found=catalog[key];break;}}if(!found){const normalized=keys.map(normalizeFoodText);found=Object.entries(catalog).find(([key,food])=>normalized.includes(normalizeFoodText(key))||normalized.includes(normalizeFoodText(food?.key||""))||normalized.includes(normalizeFoodText(food?.id||""))||normalized.includes(normalizeFoodText(food?.name||"")))?.[1]||null;}if(!found&&keys.length){const entry=(state.foodEntries||[]).find(e=>keys.includes(String(e.foodKey||""))&&e.foodSnapshot);if(entry)found=entry.foodSnapshot;}const snapshot=item?.snapshot||item?.foodSnapshot||null;if(found&&snapshot)return {...found,...snapshot,name:snapshot.name||found.name||"",unit:snapshot.unit||found.unit||"g"};return found||snapshot||null;}
 function scheduleTotals(meal){return (meal.items||[]).reduce((t,x)=>{const food=scheduleFood(x);if(!food)return t;const g=Number(x.g)||0,basis=Number(food.basisAmount)||100,factor=g/basis;t.k+=Number(food.k||0)*factor;t.p+=Number(food.p||0)*factor;t.c+=Number(food.c||0)*factor;t.f+=Number(food.f||0)*factor;return t;},{k:0,p:0,c:0,f:0});}
